{'code': "def sync_fetch(self, task):
        '''Synchronization fetch, usually used in xmlrpc thread'''
        if not self._running:
            return self.ioloop.run_sync(functools.partial(self.async_fetch, task, lambda t, _, r: True))

        wait_result = threading.Condition()
        _result = {}

        def callback(type, task, result):
            wait_result.acquire()
            _result['type'] = type
            _result['task'] = task
            _result['result'] = result
            wait_result.notify()
            wait_result.release()

        wait_result.acquire()
        self.ioloop.add_callback(self.fetch, task, callback)
        while 'result' not in _result:
            wait_result.wait()
        wait_result.release()
        return _result['result']", 'language': 'python', 'source': 'codesearchnet'}

{'code': "def _handle_aes(self, data):
        '''
        Process a command sent via an AES key

        :param str load: Encrypted payload
        :return: The result of passing the load to a function in AESFuncs corresponding to
                 the command specified in the load's 'cmd' key.
        '''
        if 'cmd' not in data:
            log.error('Received malformed command %s', data)
            return {}
        cmd = data['cmd']
        log.trace('AES payload received with command %s', data['cmd'])
        if cmd.startswith('__'):
            return False
        if self.opts['master_stats']:
            start = time.time()

        def run_func(data):
            return self.aes_funcs.run_func(data['cmd'], data)

        with StackContext(functools.partial(RequestContext,
                                            {'data': data,
                                             'opts': self.opts})):
            ret = run_func(data)

        if self.opts['master_stats']:
            stats = salt.utils.event.update_stats(self.stats, start, data)
            self._post_stats(stats)
        return ret", 'language': 'python', 'source': 'codesearchnet'}
